def group_ages_into_brackets(ages):
    brackets = {}
    for age in ages:
        start = (age // 10) * 10
        key = str(start) + '-' + str(start + 9)
        if key not in brackets:
            brackets[key] = []
        brackets[key].append(age)
    ordered = sorted(brackets, key=lambda k: int(k.split('-')[0]))
    return {k: sorted(brackets[k]) for k in ordered}

