def omega_prime_factor_count(n):
    count = 0
    factor = 2
    remaining = n
    while factor * factor <= remaining:
        while remaining % factor == 0:
            remaining //= factor
            count += 1
        factor += 1
    if remaining > 1:
        count += 1
    return count

