def zigzag_check(lst):
    n = len(lst)
    if n < 2:
        return True
    increasing = None
    for i in range(1, n):
        if lst[i] == lst[i - 1]:
            return False
        current_increasing = lst[i] > lst[i - 1]
        if increasing is not None and current_increasing == increasing:
            return False
        increasing = current_increasing
    return True

