def sort_by_abs_diff_from_median(nums):
    ordered = sorted(nums)
    n = len(ordered)
    if n % 2 == 1:
        median = float(ordered[n // 2])
    else:
        median = (ordered[n // 2 - 1] + ordered[n // 2]) / 2

    def sort_key(x):
        return (abs(x - median), x)
    return sorted(nums, key=sort_key)

