def render_numbered_padded(items):
    if not items:
        return ''
    width = len(str(len(items)))
    lines = []
    for i, item in enumerate(items, start=1):
        lines.append(f'{str(i).zfill(width)}. {item}')
    return '\n'.join(lines)

